fn linear_search(nums: Vec<i32>, target: i32) -> i32 {
    // Iterate through the vector with index
    for (idx, &val) in nums.iter().enumerate() {
        // If we find the target, return its index as i32
        if val == target {
            return idx as i32;
        }
    }
    // If we never found the target, return a negative value
    -1
}

// Example usage and simple tests
fn main() {
    let v = vec![10, 20, 30, 20, 40];
    assert_eq!(linear_search(v.clone(), 20), 1); // First occurrence of 20 is at index 1
    assert_eq!(linear_search(v.clone(), 40), 4); // 40 is at index 4
    assert_eq!(linear_search(v.clone(), 5), -1); // 5 is not in the list
    assert_eq!(linear_search(vec![], 1), -1);    // Empty list always yields -1
    println!("All tests passed!");
}